-- ============================================================
-- STAGING LAYER
-- Raw transactional tables (OLTP simulation).
-- Synthetic dataset: 250 customers, 20 products,
-- 1500 orders, 2642 order line items, 1291 payments.
-- Generated by generate_dataset.py + generate_seed_sql.py
-- ============================================================

DROP TABLE IF EXISTS stg_payments;
DROP TABLE IF EXISTS stg_order_items;
DROP TABLE IF EXISTS stg_orders;
DROP TABLE IF EXISTS stg_products;
DROP TABLE IF EXISTS stg_customers;

CREATE TABLE stg_customers (
    customer_id INT PRIMARY KEY,
    customer_name VARCHAR(100),
    gender VARCHAR(10),
    city VARCHAR(50),
    signup_date DATE
);

CREATE TABLE stg_products (
    product_id INT PRIMARY KEY,
    product_name VARCHAR(100),
    category VARCHAR(50),
    brand VARCHAR(50)
);

CREATE TABLE stg_orders (
    order_id INT PRIMARY KEY,
    customer_id INT,
    order_date DATE,
    order_status VARCHAR(20),
    FOREIGN KEY (customer_id) REFERENCES stg_customers(customer_id)
);

CREATE TABLE stg_order_items (
    order_item_id INT PRIMARY KEY,
    order_id INT,
    product_id INT,
    quantity INT,
    price DECIMAL(10,2),
    FOREIGN KEY (order_id) REFERENCES stg_orders(order_id),
    FOREIGN KEY (product_id) REFERENCES stg_products(product_id)
);

CREATE TABLE stg_payments (
    payment_id INT PRIMARY KEY,
    order_id INT,
    payment_type VARCHAR(20),
    payment_value DECIMAL(10,2),
    FOREIGN KEY (order_id) REFERENCES stg_orders(order_id)
);

